namespace ParisCheckpointHistory { namespace {
struct FSession {FString Active,Pending,Resolved;int32 PendingSerial=0;};
TMap<TWeakObjectPtr<UGameInstance>,FSession> Sessions;
FString WriteFailure;
FSession& Session(const AParisBridgeMission* M){return Sessions.FindOrAdd(UGameplayStatics::GetGameInstance(M));}
TSharedPtr<FJsonObject> Parse(const FString& S){TSharedPtr<FJsonObject> O;auto R=TJsonReaderFactory<>::Create(S);return FJsonSerializer::Deserialize(R,O)?O:nullptr;}
FString Json(const TSharedPtr<FJsonObject>& O){FString S;auto W=TJsonWriterFactory<>::Create(&S);FJsonSerializer::Serialize(O.ToSharedRef(),W);return S;}
FString LegacyHash(const FString& S){FTCHARToUTF8 U(*S);return FMD5::HashBytes(reinterpret_cast<const uint8*>(U.Get()),U.Length());}
FString Hash(const FString& S){FTCHARToUTF8 U(*S);uint8 B[20];FSHA1::HashBuffer(U.Get(),U.Length(),B);return BytesToHex(B,20);}
bool Integer(const TSharedPtr<FJsonObject>& O,const TCHAR* K,int32 Min,int32 Max,int32& N){double D;if(!O||!O->TryGetNumberField(K,D)||!FMath::IsFinite(D)||D<Min||D>Max||D!=FMath::FloorToDouble(D))return false;N=int32(D);return true;}
bool IdOK(const FString& Id){return Id==TEXT("CP0")||Id==TEXT("CP1")||Id==TEXT("G1");}
FString Base(const AParisBridgeMission* M,const FString& Id){return M->SlotPrefix+TEXT("_HC_")+Id;}
FString IndexBase(const AParisBridgeMission* M){return M->SlotPrefix+TEXT("_HI");}
FString DeletedBase(const AParisBridgeMission* M,const FString& Id){return M->SlotPrefix+TEXT("_HD_")+Id;}
TSharedPtr<FJsonObject> Header(const AParisBridgeMission* M){auto O=MakeShared<FJsonObject>();O->SetNumberField(TEXT("history_schema"),1);O->SetStringField(TEXT("mission"),M->MissionMap);O->SetStringField(TEXT("config"),M->ConfigFingerprint);return O;}
bool HeaderOK(const AParisBridgeMission* M,const TSharedPtr<FJsonObject>& O){int32 V;FString A,B;return Integer(O,TEXT("history_schema"),1,1,V)&&O->TryGetStringField(TEXT("mission"),A)&&A==M->MissionMap&&O->TryGetStringField(TEXT("config"),B)&&B==M->ConfigFingerprint;}
bool Write(const FString& Slot,const FString& Text,FString& Error){if(!WriteFailure.IsEmpty()&&Slot.Contains(WriteFailure==TEXT("record")?TEXT("_HC_"):WriteFailure==TEXT("index")?TEXT("_HI_"):TEXT("_HD_"))){WriteFailure.Reset();Error=TEXT("Declared diagnostic write failure; earlier committed data retained.");return false;}auto* S=Cast<UParisBridgeSave>(UGameplayStatics::CreateSaveGameObject(UParisBridgeSave::StaticClass()));S->Payload=Text;S->Checksum=Hash(Text);if(!UGameplayStatics::SaveGameToSlot(S,Slot,0)){Error=TEXT("Checkpoint write failed; earlier committed data retained.");return false;}auto* V=Cast<UParisBridgeSave>(UGameplayStatics::LoadGameFromSlot(Slot,0));if(!V||V->Payload!=Text||V->Checksum!=Hash(Text)){Error=TEXT("Checkpoint readback failed; earlier committed data retained.");return false;}return true;}
TSharedPtr<FJsonObject> ReadFile(const FString& Slot){auto* S=Cast<UParisBridgeSave>(UGameplayStatics::LoadGameFromSlot(Slot,0));return S&&S->Checksum==Hash(S->Payload)?Parse(S->Payload):nullptr;}
int32 Deleted(const AParisBridgeMission* M,const FString& Id){int32 Max=0;for(const TCHAR* End:{TEXT("_A"),TEXT("_B")}){auto O=ReadFile(DeletedBase(M,Id)+End);int32 N;FString Got;if(HeaderOK(M,O)&&O->TryGetStringField(TEXT("id"),Got)&&Got==Id&&Integer(O,TEXT("deleted_through"),1,2147483645,N))Max=FMath::Max(Max,N);}return Max;}
FString PayloadId(const TSharedPtr<FJsonObject>& O){const TSharedPtr<FJsonObject>* T=nullptr;FString Id;if(O&&O->TryGetObjectField(TEXT("tutorial"),T)&&(*T)->TryGetStringField(TEXT("checkpoint"),Id))return Id;return TEXT("G1");}
bool IndexOK(const AParisBridgeMission* M,const TSharedPtr<FJsonObject>& O){int32 G,N;const TArray<TSharedPtr<FJsonValue>>* A=nullptr;if(!HeaderOK(M,O)||!Integer(O,TEXT("generation"),1,2147483645,G)||!Integer(O,TEXT("high_water"),0,2147483645,N)||!O->TryGetArrayField(TEXT("entries"),A)||A->Num()>3)return false;TSet<FString> IDs;for(const auto& V:*A){const TSharedPtr<FJsonObject>* P=nullptr;FString Id,Slot;int32 Serial;if(!V->TryGetObject(P)||!(*P)->TryGetStringField(TEXT("id"),Id)||!IdOK(Id)||IDs.Contains(Id)||!(*P)->TryGetStringField(TEXT("slot"),Slot)||(Slot!=Base(M,Id)+TEXT("_A")&&Slot!=Base(M,Id)+TEXT("_B"))||!Integer(*P,TEXT("serial"),1,N,Serial))return false;IDs.Add(Id);}return true;}
TSharedPtr<FJsonObject> Index(const AParisBridgeMission* M,FString& Error){TSharedPtr<FJsonObject> Best;int32 Generation=0;for(const TCHAR* End:{TEXT("_A"),TEXT("_B")}){auto O=ReadFile(IndexBase(M)+End);if(IndexOK(M,O)&&int32(O->GetNumberField(TEXT("generation")))>Generation){Best=O;Generation=int32(O->GetNumberField(TEXT("generation")));}}if(!Best){if(HasIndex(M)){Error=TEXT("Both checkpoint directories are invalid; existing files retained.");return nullptr;}Best=Header(M);Best->SetNumberField(TEXT("generation"),0);Best->SetNumberField(TEXT("high_water"),0);Best->SetArrayField(TEXT("entries"),{});}return Best;}
bool Commit(const AParisBridgeMission* M,const TSharedPtr<FJsonObject>& O,FString& Error){const int32 G=int32(O->GetNumberField(TEXT("generation")))+1;if(G>=2147483646){Error=TEXT("Checkpoint directory limit reached.");return false;}O->SetNumberField(TEXT("generation"),G);const FString Text=Json(O),First=IndexBase(M)+(G%2?TEXT("_A"):TEXT("_B"));if(!Write(First,Text,Error))return false;FString BackupError;Write(IndexBase(M)+(G%2?TEXT("_B"):TEXT("_A")),Text,BackupError);return true;}
bool Decode(const AParisBridgeMission* M,const FString& Slot,const FString& Id,int32 Limit,FRecord& R){auto O=ReadFile(Slot);FString Got,Payload,Utc;int32 N;if(!HeaderOK(M,O)||!O->TryGetStringField(TEXT("id"),Got)||Got!=Id||!Integer(O,TEXT("serial"),1,Limit,N)||N<=Deleted(M,Id)||!O->TryGetStringField(TEXT("saved_utc"),Utc)||Utc.Len()>40||!O->TryGetStringField(TEXT("snapshot"),Payload))return false;FString E;auto P=Parse(Payload);int32 RootSerial;if(!P||PayloadId(P)!=Id||!Integer(P,TEXT("serial"),N,N,RootSerial)||!M->ValidateEquipmentReviewPayload(Payload,E))return false;R.Id=Id;R.Name=Id==TEXT("CP0")?TEXT("BASIC TRAINING"):TEXT("BRIDGEHEAD SECURED");R.Utc=Utc;R.Payload=Payload;R.Serial=N;R.Slot=Slot;return true;}
void Details(FRecord& R){auto O=Parse(R.Payload);const auto& A=O->GetArrayField(TEXT("actors"));auto P=A[0]->AsObject();R.Loaded=int32(P->GetNumberField(TEXT("loaded")));R.Reserve=int32(P->GetNumberField(TEXT("reserve")));const TSharedPtr<FJsonObject>* T=nullptr;const bool Tutorial=O->TryGetObjectField(TEXT("tutorial"),T);for(int I=1;I<3;++I)if(!A[I]->AsObject()->GetBoolField(TEXT("dead"))&&(!Tutorial||(*T)->GetArrayField(TEXT("joined"))[I-1]->AsBool()))++R.Allies;const TSharedPtr<FJsonObject>* E=nullptr;if(O->TryGetObjectField(TEXT("equipment"),E)){R.Frag=int32((*E)->GetNumberField(TEXT("frag")));R.Smoke=int32((*E)->GetNumberField(TEXT("smoke")));}}
TArray<FRecord> Legacy(const AParisBridgeMission* M){TArray<FRecord> Rows;for(const TCHAR* End:{TEXT("_A"),TEXT("_B")}){const FString Slot=M->SlotPrefix+End;auto* S=Cast<UParisBridgeSave>(UGameplayStatics::LoadGameFromSlot(Slot,0));FString E;if(!S||S->Checksum!=LegacyHash(S->Payload)||!M->ValidateEquipmentReviewPayload(S->Payload,E))continue;auto O=Parse(S->Payload);FRecord R;R.Id=PayloadId(O);if(!IdOK(R.Id))continue;R.Name=R.Id==TEXT("CP0")?TEXT("BASIC TRAINING"):TEXT("BRIDGEHEAD SECURED");R.Serial=int32(O->GetNumberField(TEXT("serial")));R.Payload=S->Payload;R.Slot=Slot;R.Utc=TEXT("Previous save");if(R.Serial<=Deleted(M,R.Id))continue;auto* Old=Rows.FindByPredicate([&](const auto& X){return X.Id==R.Id;});if(!Old)Rows.Add(R);else if(Old->Serial<R.Serial)*Old=R;}return Rows;}
int32 High(const AParisBridgeMission* M,const TSharedPtr<FJsonObject>& O){int32 H=int32(O->GetNumberField(TEXT("high_water")));for(const TCHAR* Id:{TEXT("CP0"),TEXT("CP1"),TEXT("G1")})H=FMath::Max(H,Deleted(M,Id));for(const auto& R:Legacy(M))H=FMath::Max(H,R.Serial);return H;}
TSharedPtr<FJsonObject> Envelope(const AParisBridgeMission* M,const FRecord& R){auto O=Header(M);O->SetStringField(TEXT("id"),R.Id);O->SetNumberField(TEXT("serial"),R.Serial);O->SetStringField(TEXT("saved_utc"),R.Utc);O->SetStringField(TEXT("snapshot"),R.Payload);return O;}
bool Import(const AParisBridgeMission* M,const TSharedPtr<FJsonObject>& O,FString& Error){if(HasIndex(M))return true;TArray<TSharedPtr<FJsonValue>> A;for(auto R:Legacy(M)){R.Slot=Base(M,R.Id)+TEXT("_A");if(!Write(R.Slot,Json(Envelope(M,R)),Error))return false;auto V=MakeShared<FJsonObject>();V->SetStringField(TEXT("id"),R.Id);V->SetNumberField(TEXT("serial"),R.Serial);V->SetStringField(TEXT("slot"),R.Slot);A.Add(MakeShared<FJsonValueObject>(V));}O->SetArrayField(TEXT("entries"),A);O->SetNumberField(TEXT("high_water"),High(M,O));return true;}
} // internal
bool Enabled(){static const bool On=FParse::Param(FCommandLine::Get(),TEXT("ParisCheckpointHistory"));return On;}
bool HasIndex(const AParisBridgeMission* M){return UGameplayStatics::DoesSaveGameExist(IndexBase(M)+TEXT("_A"),0)||UGameplayStatics::DoesSaveGameExist(IndexBase(M)+TEXT("_B"),0);}
TArray<FRecord> List(const AParisBridgeMission* M,FString& Error){Error.Reset();auto O=Index(M,Error);if(!O)return {};TArray<FRecord> Rows;if(!HasIndex(M))Rows=Legacy(M);else for(auto V:O->GetArrayField(TEXT("entries"))){auto E=V->AsObject();const FString Id=E->GetStringField(TEXT("id")),Slot=E->GetStringField(TEXT("slot"));const int32 Limit=int32(E->GetNumberField(TEXT("serial")));FRecord R;if(!Decode(M,Slot,Id,Limit,R)){const FString Other=Base(M,Id)+(Slot.EndsWith(TEXT("_A"))?TEXT("_B"):TEXT("_A"));if(!Decode(M,Other,Id,Limit,R))continue;R.Recovered=true;}Rows.Add(R);}Rows.Sort([](const auto& A,const auto& B){return A.Serial>B.Serial;});for(int I=0;I<Rows.Num();++I){Details(Rows[I]);Rows[I].Latest=I==0;Rows[I].Active=Rows[I].Id==Session(M).Active;}if(Rows.IsEmpty()&&Error.IsEmpty())Error=TEXT("No valid checkpoint is available.");return Rows;}
int32 NextSerial(const AParisBridgeMission* M,FString& Error){Error.Reset();auto O=Index(M,Error);if(!O)return 0;const int32 N=High(M,O)+1;if(N>=2147483646){Error=TEXT("Checkpoint revision limit reached.");return 0;}return N;}
bool Save(AParisBridgeMission* M,const FString& Payload,FString& Error){if(!M->ValidateEquipmentReviewPayload(Payload,Error))return false;auto O=Index(M,Error);if(!O||!Import(M,O,Error))return false;auto Root=Parse(Payload);FRecord R;R.Id=PayloadId(Root);R.Serial=int32(Root->GetNumberField(TEXT("serial")));if(!IdOK(R.Id)||R.Serial!=High(M,O)+1){Error=TEXT("Checkpoint identity or revision changed; retry saving.");return false;}auto A=O->GetArrayField(TEXT("entries"));int32 Found=INDEX_NONE;FString Current;for(int I=0;I<A.Num();++I)if(A[I]->AsObject()->GetStringField(TEXT("id"))==R.Id){Found=I;Current=A[I]->AsObject()->GetStringField(TEXT("slot"));}R.Slot=Base(M,R.Id)+(Current.EndsWith(TEXT("_A"))?TEXT("_B"):TEXT("_A"));R.Payload=Payload;R.Utc=FDateTime::UtcNow().ToIso8601();if(!Write(R.Slot,Json(Envelope(M,R)),Error))return false;FRecord Verify;if(!Decode(M,R.Slot,R.Id,R.Serial,Verify)||Verify.Payload!=Payload){Error=TEXT("New checkpoint snapshot did not validate after write.");return false;}auto E=MakeShared<FJsonObject>();E->SetStringField(TEXT("id"),R.Id);E->SetStringField(TEXT("slot"),R.Slot);E->SetNumberField(TEXT("serial"),R.Serial);if(Found==INDEX_NONE)A.Add(MakeShared<FJsonValueObject>(E));else A[Found]=MakeShared<FJsonValueObject>(E);O->SetArrayField(TEXT("entries"),A);O->SetNumberField(TEXT("high_water"),R.Serial);if(!Commit(M,O,Error))return false;Session(M).Active=R.Id;Session(M).Pending.Reset();return true;}
bool Read(const AParisBridgeMission* M,FString& Payload,int32& Serial,FString& Error){auto Rows=List(M,Error);if(Rows.IsEmpty())return false;auto& S=Session(M);const FString Id=!S.Pending.IsEmpty()?S.Pending:S.Active;const FRecord* R=Rows.FindByPredicate([&](const auto& V){return V.Id==Id;});if(!R){if(!S.Pending.IsEmpty()){Error=TEXT("Selected checkpoint is unavailable; no different point was loaded.");return false;}R=&Rows[0];}if(!S.Pending.IsEmpty()&&S.PendingSerial!=R->Serial){Error=TEXT("Selected checkpoint changed; choose it again.");return false;}Payload=R->Payload;Serial=R->Serial;S.Resolved=R->Id;Error=R->Recovered?TEXT("Recovered validated backup of this checkpoint."):FString();return true;}
bool PrepareLoad(AParisBridgeMission* M,const FString& Id,int32 Expected,FString& Error){auto Rows=List(M,Error);const auto* R=Rows.FindByPredicate([&](const auto& V){return V.Id==Id;});if(!R||Expected&&R->Serial!=Expected){Error=TEXT("Checkpoint changed or is unavailable; select it again.");return false;}auto& S=Session(M);S.Pending=Id;S.PendingSerial=R->Serial;return true;}
bool Delete(AParisBridgeMission* M,const FString& Id,int32 Expected,FString& Error){auto Rows=List(M,Error);if(Rows.IsEmpty())return false;const auto* R=Rows.FindByPredicate([&](const auto& V){return V.Id==Id;});if(!R||R->Serial!=Expected){Error=TEXT("Checkpoint changed; deletion cancelled.");return false;}if(R->Latest){Error=TEXT("The latest valid checkpoint cannot be deleted.");return false;}auto O=Index(M,Error);if(!O||!Import(M,O,Error))return false;const int32 Limit=High(M,O);auto T=Header(M);T->SetStringField(TEXT("id"),Id);T->SetNumberField(TEXT("deleted_through"),Limit);const FString Text=Json(T);if(!Write(DeletedBase(M,Id)+TEXT("_A"),Text,Error))return false;FString Warn;Write(DeletedBase(M,Id)+TEXT("_B"),Text,Warn);TArray<TSharedPtr<FJsonValue>> Kept;for(auto E:O->GetArrayField(TEXT("entries")))if(E->AsObject()->GetStringField(TEXT("id"))!=Id)Kept.Add(E);O->SetArrayField(TEXT("entries"),Kept);O->SetNumberField(TEXT("high_water"),Limit);Commit(M,O,Warn);bool Clean=true;for(const TCHAR* End:{TEXT("_A"),TEXT("_B")}){const FString Slot=Base(M,Id)+End;if(UGameplayStatics::DoesSaveGameExist(Slot,0))Clean&=UGameplayStatics::DeleteGameInSlot(Slot,0);}if(Session(M).Active==Id)Session(M).Active=Rows[0].Id;Session(M).Pending.Reset();Error=Clean&&Warn.IsEmpty()?FString():TEXT("Record removed; some recovery files could not be cleaned. Latest checkpoint retained.");return true;}
void Loaded(AParisBridgeMission* M){auto& S=Session(M);S.Active=S.Resolved;S.Pending.Reset();S.PendingSerial=0;}
void Restart(AParisBridgeMission* M){auto& S=Session(M);S.Active.Reset();S.Pending.Reset();S.PendingSerial=0;}
FString Active(const AParisBridgeMission* M){return Session(M).Active;}
bool ArmDiagnosticWriteFailure(const FString& Kind){FString Mode;if(!FParse::Value(FCommandLine::Get(),TEXT("ParisHistoryCheck="),Mode)||Mode!=TEXT("storage_faults")||(Kind!=TEXT("record")&&Kind!=TEXT("index")&&Kind!=TEXT("delete")))return false;WriteFailure=Kind;return true;}
} // namespace
